mkdir -p /project/work/p21_113 /project/work/p21_29 /project/work/p21_99 && cat > /project/work/p21_113/psi_check.g <<'EOF'
# Problem 21.113(a) (G. Robinson): Psi_{p,G}(x) = 0 if x p-singular, else = number of p-elements in C_G(x).
# Check whether Psi is a (proper) character for all small groups of order in [lo,hi].
IsPElt := function(g, p) return IsPrimePowerInt(Order(g)) and Order(g) mod p = 0 or Order(g)=1; end;
PsiCheck := function(G, p)
  local tbl, cls, reps, psi, i, x, C, cnt, irr, ip, chi, ok, bad;
  tbl := CharacterTable(G);
  cls := ConjugacyClasses(tbl);
  reps := List(cls, Representative);
  psi := [];
  for i in [1..Length(reps)] do
    x := reps[i];
    if Order(x) mod p = 0 then
      Add(psi, 0);
    else
      C := Centralizer(G, x);
      cnt := Number(C, y -> IsPElt(y,p));
      Add(psi, cnt);
    fi;
  od;
  irr := Irr(tbl);
  bad := [];
  for chi in irr do
    ip := ScalarProduct(tbl, psi, chi);
    if not (IsInt(ip) and ip >= 0) then Add(bad, ip); fi;
  od;
  return bad;
end;
lo := Int(GAPInfo.CommandLineOptions.Arguments[1] );
EOF
echo; cat > /project/work/p21_113/run.g <<'EOF'
Read("/project/work/p21_113/psi_check.g");
CheckRange := function(lo, hi)
  local n, k, G, p, bad, total;
  total := 0;
  for n in [lo..hi] do
    if n in [512, 1024, 1536] then continue; fi;
    for k in [1..NrSmallGroups(n)] do
      G := SmallGroup(n, k);
      for p in PrimeDivisors(n) do
        bad := PsiCheck(G, p);
        total := total + 1;
        if Length(bad) > 0 then
          Print("COUNTEREXAMPLE? SmallGroup(", n, ",", k, ") p=", p, " bad inner products: ", bad, "\n");
        fi;
      od;
    od;
    Print("done order ", n, " (", NrSmallGroups(n), " groups) checked ", total, " pairs\n");
  od;
end;
EOF
echo ok

