Read("/project/work/p21_99/check.g");
RunDegrees(2, 31); QUIT;
EOF
cat > run2.g <<'EOF'
Read("/project/work/p21_99/check.g");
RunDegrees(33, 47); QUIT;
EOF
cat > run3.g <<'EOF'
