input.command:
cat > brauer_lib.g <<'EOF'
# 21.113(b) via library character tables (ordinary + Brauer).
# Psi(x) for p-regular x = number of p-elements in C_G(x) = sum over classes D of p-elements of |D meet C(x)|,
# |D meet C(x)| = (|D|/|G|) sum_chi |chi(x)|^2 |chi(y)|^2 / chi(1)^2  (Frobenius count of commuting pairs / |C_x|).
PsiFromTable := function(tbl, p)
  local irr, ords, sizes, n, pcl, psi, i, j, s, chi, order;
  irr := Irr(tbl); ords := OrdersClassRepresentatives(tbl); sizes := SizesConjugacyClasses(tbl);
  n := Length(ords); order := Size(tbl);
  pcl := Filtered([1..n], j -> ords[j] = 1 or (IsPrimePowerInt(ords[j]) and ords[j] mod p = 0));
  psi := [];
  for i in [1..n] do
    if ords[i] mod p = 0 then Add(psi, 0);
    else
      s := 0;
      for j in pcl do
        s := s + sizes[j] * Sum(irr, chi -> (chi[i]*ComplexConjugate(chi[i]))*(chi[j]*ComplexConjugate(chi[j]))/chi[1]^2);
      od;
