  while(i<n){ if(c[i]<i){ if(i%2==0){int t=p[0];p[0]=p[i];p[i]=t;} else {int t=p[c[i]];p[c[i]]=p[i];p[i]=t;} memcpy(perms[nperms++],p,sizeof(int)*n); c[i]++; i=0;} else {c[i]=0;i++;} } }
