# 17.128 (Jabara): T p-group, A = C_p^2 acting, P = T A, every element of P \ T of order p => exp(T) = p ?
CheckOrder := function(n)
  local p, k, P, cnt, T, comp, A, ok, x, cls, c;
  p := PrimeDivisors(n)[1]; cnt := 0;
  for k in [1..NrSmallGroups(n)] do
