# 20.55 (Mattarei): soluble G, H with identical character tables and derived lengths 2 and 4?
for n in [48..1000] do
  if NrSmallGroups(n) > 3000 then continue; fi;
  dl4 := []; dl2 := [];
  for k in [1..NrSmallGroups(n)] do
