# Export, for each group of exponent 3 and order 729 (and order 243), all subgroups of order 27 (resp. 9) as element index sets.
Export := function(n, k, out)
  local G, elts, pos, ccs, subs, S, line;
  G := SmallGroup(n, k);
  elts := Elements(G);
  ccs := List(ConjugacyClassesSubgroups(G), Representative);
