  # check the coboundaries are killed
  Print("  l_h vanish on coboundaries: ", ForAll(BasisVectors(Basis(cd.B)), b -> ForAll(cd.rows, r -> IsZero(r*b))), "\n");
  # export the distinct nonzero functionals as bit rows for the C solver
