  SetPrintFormattingStatus(out, false);
  WriteLine(out, Concatenation(String(Length(rowsS)), " ", String(cd.m)));
  for r in rowsS do WriteLine(out, Concatenation(List(r, x -> String(IntFFE(x))))); od;
  CloseStream(out);
od;
QUIT;
EOF
