  SetPrintFormattingStatus(out, false);
  WriteLine(out, Concatenation(String(Length(rowsS)), " ", String(cd.m)));
  for row in rowsS do WriteLine(out, Concatenation(List(row, x -> String(IntFFE(x))))); od;
  CloseStream(out);
